import subprocess
import sys
from pathlib import Path

subprocess.run(
    [sys.executable, "-m", "pip", "install", "-q", "transformers==4.57.6",
     "sacrebleu==2.5.1", "sentencepiece", "accelerate", "sacremoses",
     "entmax", "jsonargparse==3.13.1", "torchmetrics==0.10.3", "pytorch-lightning"],
    check=True,
)
subprocess.run(
    [sys.executable, "-m", "pip", "install", "-q", "--no-deps", "unbabel-comet==2.2.7"],
    check=True,
)

import base64
import io
import os
import zipfile
os.environ["CUDA_VISIBLE_DEVICES"] = "0"
root = Path("/tmp/taf")
with zipfile.ZipFile(io.BytesIO(base64.b64decode(''))) as bundle:
    bundle.extractall(root)
subprocess.run(
    [sys.executable, "-u", str(root / "scripts/reproduce_de_en.py"),
     "--data", str(root / "data/dev.tsv"), "--policy", "ralcp_taf", "--beam-width", "4", "--ralcp-fraction", "0.6", "--n", "4",
     "--horizon", "6", "--initial-read", "3", "--device", "cuda", "--dtype", "float16",
     "--llm-backend", "hf", "--llm-model", "Qwen/Qwen2.5-0.5B",
     "--mt-backend", "hf", "--mt-model", "Helsinki-NLP/opus-mt-de-en",
     "--comet-model", "Unbabel/wmt22-comet-da", "--output-dir", "/kaggle/working/taf_smoke"],
    check=True,
)
